{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C22"],
      "claim": "A human absolute bioavailability study reported 41 ± 18%, above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "In healthy subjects, absolute oral bioavailability was 63%, clearly above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "In young healthy subjects, absolute bioavailability was 19% ± 7%, below the 20% threshold.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "High is better supported: multiple high-score human absolute oral bioavailability records are above 20% (41%, 63%, 27–35%), whereas the strongest numeric negative is borderline (19%) and the clearly low values (<3%, 8–10%) have lower assay-transfer scores; qualitative low statements are discounted.",
  "evidence_gaps": [
    "No record explicitly states fasted-state conditions; transfer from ordinary oral studies is indirect.",
    "Molecule 6 has conflicting absolute values (≈20% at 10 g vs 68% at 6 g) and one record (C07) refers to citrulline rather than L-arginine, a provenance conflict.",
    "Several records are qualitative ('not high enough', 'low', 'high') without numeric F values, limiting threshold determination."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

